{
    /// <summary>
    ///     URL of the link
    /// </summary>
    [JsonPropertyName("url")]
    public string Url { get; init; } = default!;
}

/// <summary>
///     At most one of the optional fields can be present in any given object.
/// </summary>
/// <remarks><see href="https://core.telegram.org/bots/api#pollmedia"/></remarks>
public sealed record PollMedia : BotApiObject
{
    /// <summary>
    ///     Optional. Media is an animation, information about the animation
    /// </summary>
    [JsonPropertyName("animation")]
    public Animation? Animation { get; init; }

    /// <summary>
    ///     Optional. Media is an audio file, information about the file; currently, can't be received in a poll option
    /// </summary>
    [JsonPropertyName("audio")]
    public Audio? Audio { get; init; }

    /// <summary>
    ///     Optional. Media is a general file, information about the file; currently, can't be received in a poll option
    /// </summary>
    [JsonPropertyName("document")]
    public Document? Document { get; init; }

    /// <summary>
    ///     Optional. The HTTP link attached to the poll option
    /// </summary>
    [JsonPropertyName("link")]
    public Link? Link { get; init; }

    /// <summary>
    ///     Optional. Media is a live photo, information about the live photo
    /// </summary>
    [JsonPropertyName("live_photo")]
    public LivePhoto? LivePhoto { get; init; }

    /// <summary>
    ///     Optional. Media is a shared location, information about the location
    /// </summary>
    [JsonPropertyName("location")]
    public Location? Location { get; init; }

    /// <summary>
    ///     Optional. Media is a photo, available sizes of the photo
    /// </summary>
    [JsonPropertyName("photo")]
    public IReadOnlyList<PhotoSize>? Photo { get; init; }

    /// <summary>
    ///     Optional. Media is a sticker, information about the sticker; currently, for poll options only
    /// </summary>
    [JsonPropertyName("sticker")]
    public Sticker? Sticker { get; init; }

    /// <summary>
    ///     Optional. Media is a venue, information about the venue
    /// </summary>
    [JsonPropertyName("venue")]
    public Venue? Venue { get; init; }

    /// <summary>
    ///     Optional. Media is a video, information about the video
    /// </summary>
    [JsonPropertyName("video")]
    public Video? Video { get; init; }
}

/// <summary>
///     This object contains information about one answer option in a poll.
/// </summary>
/// <remarks><see href="https://core.telegram.org/bots/api#polloption"/></remarks>
public sealed record PollOption : BotApiObject
{
    /// <summary>
    ///     Unique identifier of the option, persistent on option addition and deletion
    /// </summary>
    [JsonPropertyName("persistent_id")]
    public string PersistentId { get; init; } = default!;

    /// <summary>
    ///     Option text, 1-100 characters
    /// </summary>
    [JsonPropertyName("text")]
    public string Text { get; init; } = default!;

    /// <summary>
    ///     Optional. Special entities that appear in the option text. Currently, only custom emoji entities are allowed in poll option texts
    /// </summary>
    [JsonPropertyName("text_entities")]
    public IReadOnlyList<MessageEntity>? TextEntities { get; init; }

    /// <summary>
    ///     Optional. Media added to the poll option
    /// </summary>
    [JsonPropertyName("media")]
    public PollMedia? Media { get; init; }

    /// <summary>
    ///     Number of users who voted for this option; may be 0 if unknown
    /// </summary>
    [JsonPropertyName("voter_count")]
    public long VoterCount { get; init; }

    /// <summary>
    ///     Optional. User who added the option; omitted if the option wasn't added by a user after poll creation
    /// </summary>
    [JsonPropertyName("added_by_user")]
    public User? AddedByUser { get; init; }

    /// <summary>
    ///     Optional. Chat that added the option; omitted if the option wasn't added by a chat after poll creation
    /// </summary>
    [JsonPropertyName("added_by_chat")]
    public Chat? AddedByChat { get; init; }

    /// <summary>
    ///     Optional. Point in time (Unix timestamp) when the option was added; omitted if the option existed in the original poll
    /// </summary>
    [JsonPropertyName("addition_date")]
    public long? AdditionDate { get; init; }
}

/// <summary>
///     This object contains information about one answer option in a poll to be sent.
/// </summary>
/// <remarks><see href="https://core.telegram.org/bots/api#inputpolloption"/></remarks>
public sealed record InputPollOption : BotApiObject
{
    /// <summary>
    ///     Option text, 1-100 characters
    /// </summary>
    [JsonPropertyName("text")]
    public string Text { get; init; } = default!;

    /// <summary>
    ///     Optional. Mode for parsing entities in the text. See formatting options for more details. Currently, only custom emoji entities are allowed.
    /// </summary>
    [JsonPropertyName("text_parse_mode")]
    public string? TextParseMode { get; init; }

    /// <summary>
    ///     Optional. A JSON-serialized list of special entities that appear in the poll option text. It can be specified instead of text_parse_mode.
    /// </summary>
    [JsonPropertyName("text_entities")]
    public IReadOnlyList<MessageEntity>? TextEntities { get; init; }

    /// <summary>
    ///     Optional. Media added to the poll option
    /// </summary>
    [JsonPropertyName("media")]
    public InputPollOptionMedia? Media { get; init; }
}

/// <summary>
///     This object represents an answer of a user in a non-anonymous poll.
/// </summary>
/// <remarks><see href="https://core.telegram.org/bots/api#pollanswer"/></remarks>
public sealed record PollAnswer : BotApiObject
{
    /// <summary>
    ///     Unique poll identifier
    /// </summary>
    [JsonPropertyName("poll_id")]
    public string PollId { get; init; } = default!;

    /// <summary>
    ///     Optional. The chat that changed the answer to the poll, if the voter is anonymous
    /// </summary>
    [JsonPropertyName("voter_chat")]
    public Chat? VoterChat { get; init; }

    /// <summary>
    ///     Optional. The user that changed the answer to the poll, if the voter isn't anonymous
    /// </summary>
    [JsonPropertyName("user")]
    public User? User { get; init; }

    /// <summary>
    ///     0-based identifiers of chosen answer options. May be empty if the vote was retracted.
    /// </summary>
    [JsonPropertyName("option_ids")]
    public IReadOnlyList<long> OptionIds { get; init; } = [];

    /// <summary>
    ///     Persistent identifiers of the chosen answer options. May be empty if the vote was retracted.
    /// </summary>
    [JsonPropertyName("option_persistent_ids")]
    public IReadOnlyList<string> OptionPersistentIds { get; init; } = [];
}

/// <summary>
///     This object contains information about a poll.
/// </summary>
/// <remarks><see href="https://core.telegram.org/bots/api#poll"/></remarks>
public sealed record Poll : BotApiObject
{
    /// <summary>
    ///     Unique poll identifier
    /// </summary>
    [JsonPropertyName("id")]
    public string Id { get; init; } = default!;

    /// <summary>
    ///     Poll question, 1-300 characters
    /// </summary>
    [JsonPropertyName("question")]
    public string Question { get; init; } = default!;

    /// <summary>
    ///     Optional. Special entities that appear in the question. Currently, only custom emoji entities are allowed in poll questions
    /// </summary>
    [JsonPropertyName("question_entities")]
    public IReadOnlyList<MessageEntity>? QuestionEntities { get; init; }

    /// <summary>
    ///     List of poll options
    /// </summary>
    [JsonPropertyName("options")]
    public IReadOnlyList<PollOption> Options { get; init; } = [];

    /// <summary>
    ///     Total number of users that voted in the poll
    /// </summary>
    [JsonPropertyName("total_voter_count")]
    public long TotalVoterCount { get; init; }

    /// <summary>
    ///     True, if the poll is closed
    /// </summary>
    [JsonPropertyName("is_closed")]
    public bool IsClosed { get; init; }

    /// <summary>
    ///     True, if the poll is anonymous
    /// </summary>
    [JsonPropertyName("is_anonymous")]
    public bool IsAnonymous { get; init; }

    /// <summary>
    ///     Poll type, currently can be "regular" or "quiz"
    /// </summary>
    [JsonPropertyName("type")]
    public string Type { get; init; } = default!;

    /// <summary>
    ///     True, if the poll allows multiple answers
    /// </summary>
    [JsonPropertyName("allows_multiple_answers")]
    public bool AllowsMultipleAnswers { get; init; }

    /// <summary>
    ///     True, if the poll allows to change the chosen answer options
    /// </summary>
    [JsonPropertyName("allows_revoting")]
    public bool AllowsRevoting { get; init; }

    /// <summary>
    ///     True if voting is limited to users who have been members of the chat where the poll was originally sent for more than 24 hours
    /// </summary>
    [JsonPropertyName("members_only")]
    public bool MembersOnly { get; init; }

    /// <summary>
    ///     Optional. A list of two-letter ISO 3166-1 alpha-2 country codes indicating the countries from which users can vote in the poll. The country code "FT" is used for users with anonymous numbers. If omitted, then users from any country can participate in the poll.
    /// </summary>
    [JsonPropertyName("country_codes")]
    public IReadOnlyList<string>? CountryCodes { get; init; }

    /// <summary>
    ///     Optional. Array of 0-based identifiers of the correct answer options. Available only for polls in quiz mode which are closed or were sent (not forwarded) by the bot or to the private chat with the bot.
    /// </summary>
    [JsonPropertyName("correct_option_ids")]
    public IReadOnlyList<long>? CorrectOptionIds { get; init; }

    /// <summary>
    ///     Optional. Text that is shown when a user chooses an incorrect answer or taps on the lamp icon in a quiz-style poll, 0-200 characters
    /// </summary>
    [JsonPropertyName("explanation")]
    public string? Explanation { get; init; }

    /// <summary>
    ///     Optional. Special entities like usernames, URLs, bot commands, etc. that appear in the explanation
    /// </summary>
    [JsonPropertyName("explanation_entities")]
    public IReadOnlyList<MessageEntity>? ExplanationEntities { get; init; }

    /// <summary>
    ///     Optional. Media added to the quiz explanation
    /// </summary>
    [JsonPropertyName("explanation_media")]
    public PollMedia? ExplanationMedia { get; init; }

    /// <summary>
    ///     Optional. Amount of time in seconds the poll will be active after creation
    /// </summary>
    [JsonPropertyName("open_period")]
    public long? OpenPeriod { get; init; }

    /// <summary>
    ///     Optional. Point in time (Unix timestamp) when the poll will be automatically closed
    /// </summary>
    [JsonPropertyName("close_date")]
    public long? CloseDate { get; init; }

    /// <summary>
    ///     Optional. Description of the poll; for polls inside the Message object only
    /// </summary>
    [JsonPropertyName("description")]
    public string? Description { get; init; }

    /// <summary>
    ///     Optional. Special entities like usernames, URLs, bot commands, etc. that appear in the description
    /// </summary>
    [JsonPropertyName("description_entities")]
    public IReadOnlyList<MessageEntity>? DescriptionEntities { get; init; }

    /// <summary>
    ///     Optional. Media added to the poll description; for polls inside the Message object only
    /// </summary>
    [JsonPropertyName("media")]
    public PollMedia? Media { get; init; }
}

